namespace SmartSolar.Modules.CustomerContracts;

/// <summary>
/// Business ownership state of a 30/70 contract (derived; not a legal certificate or transfer). Legal effect of the retention clause depends on Legal's
/// review (BLDS 2015 Art. 331–332); the system never repossesses or decides anything legal.
/// </summary>
public static class OwnershipStatuses
{
    public const string Retained = "OWNERSHIP_RETAINED";
    public const string TransferEligible = "OWNERSHIP_TRANSFER_ELIGIBLE";
    /// <summary>Legacy full-payment contract or a discarded contract: no retention clause generated by this plan.</summary>
    public const string NotApplicable = "NOT_APPLICABLE";
}

/// <summary>Where a 30/70 contract stands (derived from contract status + installments). SIGNED ≠ FULLY_PAID.</summary>
public static class PaymentPlanStages
{
    /// <summary>Created at the agreement; the customer can preview it; deposit due.</summary>
    public const string DraftCreated = "DRAFT_CREATED";
    /// <summary>Deposit verified; the paper contract may be signed.</summary>
    public const string DepositVerified = "DEPOSIT_VERIFIED";
    /// <summary>Paper signed and finalized after the deposit: ready for installation (balance waits for acceptance).</summary>
    public const string ReadyForInstallation = "READY_FOR_INSTALLATION";
    /// <summary>Customer accepted; balance due before its deadline.</summary>
    public const string BalanceDue = "BALANCE_DUE";
    /// <summary>Balance deadline passed without payment.</summary>
    public const string BalanceOverdue = "BALANCE_OVERDUE";
    public const string FullyPaid = "FULLY_PAID";
    public const string Discarded = "DISCARDED";
}

public sealed record InstallmentView(Guid InstallmentId, int Sequence, string Kind, decimal Percent, decimal Amount, string Status, DateTimeOffset? OpenedAt,
    DateTimeOffset? DueAt, bool Overdue, DateTimeOffset? PaidAt, decimal? PaidAmount, bool PaidLate, Guid? SettledPaymentAttemptId);

public sealed record CollectionCaseSummaryView(Guid CaseId, Guid InstallmentId, string Status, DateTimeOffset OpenedAt, DateTimeOffset DueAt, decimal AmountDue,
    DateOnly? PromisedPaymentDate, DateTimeOffset? ResolvedAt, string? Resolution);

/// <param name="TermsPendingLegalReview">The generated payment / ownership clauses carry a version still marked as pending legal approval.</param>
/// <param name="LegalReviewRequired">An open collection case was sent to legal review.</param>
/// <param name="Collection">Staff views only.</param>
public sealed record ContractPaymentPlanView(string Plan, string? TermsVersion, string Stage, decimal Total, decimal Paid, decimal Outstanding, bool DepositPaid,
    bool PaperSigned, bool ReadyForInstallation, bool FullyPaid, bool Overdue, DateTimeOffset? NextDueAt, string OwnershipStatus, bool TermsPendingLegalReview,
    bool LegalReviewRequired, IReadOnlyList<InstallmentView> Installments, SignatureSetView? Signature, IReadOnlyList<CollectionCaseSummaryView>? Collection);

public static class PaymentPlanViews
{
    public static ContractPaymentPlanView? Build(CustomerContract c, IReadOnlyList<ContractInstallment> installments, IReadOnlyList<ContractSignatureSet> sets,
        IReadOnlyList<ContractSignedPage> pages, IReadOnlyList<ContractCollectionCase>? cases, DateTimeOffset now)
    {
        if (c.PaymentPlan is null) return null;
        var summary = PaymentPlanCalculator.Summarize(c.TotalAmount, installments, now);
        var current = sets.FirstOrDefault(s => s.Status != SignatureSetStatuses.Superseded);
        var paperSigned = current?.Status == SignatureSetStatuses.Finalized;
        var balance = installments.FirstOrDefault(i => i.Kind == InstallmentKinds.Balance);
        var stage = c.Status == ContractStatuses.Discarded ? PaymentPlanStages.Discarded
            : summary.FullyPaid ? PaymentPlanStages.FullyPaid
            : balance?.Status == InstallmentStatuses.Due ? (summary.Overdue ? PaymentPlanStages.BalanceOverdue : PaymentPlanStages.BalanceDue)
            : c.Status == ContractStatuses.Signed ? PaymentPlanStages.ReadyForInstallation
            : summary.DepositPaid ? PaymentPlanStages.DepositVerified
            : PaymentPlanStages.DraftCreated;
        var ownership = c.Status == ContractStatuses.Discarded ? OwnershipStatuses.NotApplicable
            : summary.FullyPaid ? OwnershipStatuses.TransferEligible
            : OwnershipStatuses.Retained;
        return new ContractPaymentPlanView(c.PaymentPlan, c.TermsVersion, stage, summary.Total, summary.Paid, summary.Outstanding, summary.DepositPaid, paperSigned,
            ContractStatuses.IsReadyForInstallation(c.Status, c.PaymentPlan), summary.FullyPaid, summary.Overdue, summary.NextDueAt, ownership,
            c.TermsVersion?.Contains("PENDING_LEGAL_REVIEW", StringComparison.Ordinal) ?? false,
            cases?.Any(x => x.Status == CollectionCaseStatuses.LegalReviewRequired) ?? false,
            installments.OrderBy(i => i.Sequence).Select(i => View(i, now)).ToList(),
            current is null ? null : PaperSignatureHandlers.View(current, pages),
            cases?.Select(x => new CollectionCaseSummaryView(x.Id, x.InstallmentId, x.Status, x.OpenedAt, x.DueAt, x.AmountDue, x.PromisedPaymentDate, x.ResolvedAt,
                x.Resolution)).ToList());
    }

    public static InstallmentView View(ContractInstallment i, DateTimeOffset now) => new(i.Id, i.Sequence, i.Kind, i.Percent, i.Amount, i.Status, i.OpenedAt, i.DueAt,
        PaymentPlanCalculator.IsOverdue(i, now), i.PaidAt, i.PaidAmount, i.PaidLate, i.SettledPaymentAttemptId);
}
